pattern.code:
import { sanitizeCodeOutput } from '../tools/output-sanitizer.js';

// In agent loop, after receiving code execution result:
const cleanOutput = sanitizeCodeOutput(rawOutput);
// Use cleanOutput in response to user

import { humanizeError } from '../tools/error-humanizer.js';

catch (e) {
  const humanized = humanizeError(e);
  logger.error({
    event: 'tool.execution.failed',
    technicalDetails: humanized.technicalDetails,
    errorType: humanized.errorType,
    traceId
  });
  return {
    success: false,
    error: {
      code: 'TOOL_EXECUTION_FAILED',
      message: humanized.userMessage,
      retryable: isRetryable(e)
    }
  };
}

import { formatToolSummary, ToolAction } from '../tools/tool-summary.js';

await setStatus({
  status: 'thinking...',
  loading_messages: [
    formatToolSummary({ toolName: 'Confluence', action: 'search', context: query }),
    formatToolSummary({ toolName: 'Jira', action: 'call', context: 'issue lookup' }),
    formatToolSummary({ toolName: 'code', action: 'execute', context: 'data analysis' }),
  ],
});
